import{_ as a,o as r,c as o,a2 as i}from"./chunks/framework.wVcpyw2-.js";const b=JSON.parse('{"title":"账号权限与权限模板","description":"灵萌管理后台账号权限配置：如何给管理员分配菜单与按钮权限、使用权限模板、排查侧栏空白。","frontmatter":{"title":"账号权限与权限模板","description":"灵萌管理后台账号权限配置：如何给管理员分配菜单与按钮权限、使用权限模板、排查侧栏空白。"},"headers":[],"relativePath":"config/admin-permissions.md","filePath":"config/admin-permissions.md","lastUpdated":1785020677000}'),d={name:"config/admin-permissions.md"};function l(e,t,n,s,h,g){return r(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="账号权限与权限模板" tabindex="-1">账号权限与权限模板 <a class="header-anchor" href="#账号权限与权限模板" aria-label="Permalink to &quot;账号权限与权限模板&quot;">​</a></h1><p>路径：<strong>系统设置 → 账号权限</strong> / <strong>系统设置 → 权限模板</strong></p><p>给运营、区域负责人分配「能看哪些菜单、能点哪些按钮」。未正确授权时，对方登录后台会侧栏空白或接口报无权限。</p><div class="warning custom-block"><p class="custom-block-title">重要变化</p><p>管理员账号<strong>必须</strong>配置授权（勾选权限或套用模板）后才能访问后台接口。未配置任何授权时，系统默认拒绝访问（超级管理员除外）。</p></div><hr><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>您是<strong>超级管理员</strong>，或已被授予「账号权限 / 权限模板」写权限</li><li>目标账号已是管理员身份（平台管理员、区域主/子负责人等），普通用户不会出现在可配置列表中</li><li><strong>系统设置</strong>类权限（系统配置、账号权限等）<strong>仅可授予超级管理员或平台管理员</strong>，不能分给区域负责人</li></ul><hr><h2 id="推荐做法-先模板-再套用" tabindex="-1">推荐做法：先模板，再套用 <a class="header-anchor" href="#推荐做法-先模板-再套用" aria-label="Permalink to &quot;推荐做法：先模板，再套用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>菜单</th><th>做什么</th></tr></thead><tbody><tr><td>1</td><td><strong>权限模板</strong></td><td>按岗位建模板（如「内容运营」「区域客服」）</td></tr><tr><td>2</td><td><strong>账号权限</strong></td><td>选中账号 → 套用模板 → 个别增减 → 保存</td></tr></tbody></table><p>日常加人时：套用现成模板即可，不必每次从零勾选。</p><hr><h2 id="一、权限模板" tabindex="-1">一、权限模板 <a class="header-anchor" href="#一、权限模板" aria-label="Permalink to &quot;一、权限模板&quot;">​</a></h2><p>路径：<strong>系统设置 → 权限模板</strong></p><h3 id="新建模板" tabindex="-1">新建模板 <a class="header-anchor" href="#新建模板" aria-label="Permalink to &quot;新建模板&quot;">​</a></h3><ol><li>点右上角 <strong>+ 新建模板</strong></li><li>填写： <ul><li><strong>模板名称</strong>（如「内容审核员」）</li><li><strong>描述</strong>（可选）</li><li><strong>适用对象</strong>：平台管理员 / 区域负责人</li></ul></li><li>保存后，在左侧列表选中该模板</li><li>在右侧勾选权限（可用 <strong>全选 / 清空</strong>）</li><li>点 <strong>保存权限</strong></li></ol><p>权限树顺序与侧栏一致：<strong>一级目录 → 二级目录 → 页面菜单 → 按钮</strong>。</p><ul><li>只勾「菜单访问」：能进页面、能查列表</li><li>再勾对应「按钮」：才能审核通过、删除、保存配置等写操作</li></ul><h3 id="维护模板" tabindex="-1">维护模板 <a class="header-anchor" href="#维护模板" aria-label="Permalink to &quot;维护模板&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><strong>编辑信息</strong></td><td>改名称、描述、适用对象</td></tr><tr><td><strong>保存权限</strong></td><td>保存当前勾选；保存后会替换该模板全部授权项</td></tr><tr><td><strong>删除</strong></td><td>删除模板；已套用该模板的账号需重新检查权限</td></tr></tbody></table><hr><h2 id="二、账号权限" tabindex="-1">二、账号权限 <a class="header-anchor" href="#二、账号权限" aria-label="Permalink to &quot;二、账号权限&quot;">​</a></h2><p>路径：<strong>系统设置 → 账号权限</strong></p><h3 id="界面说明" tabindex="-1">界面说明 <a class="header-anchor" href="#界面说明" aria-label="Permalink to &quot;界面说明&quot;">​</a></h3><table tabindex="0"><thead><tr><th>区域</th><th>作用</th></tr></thead><tbody><tr><td>顶部身份 Tab</td><td>全部 / 超级管理员 / 平台管理员 / 区域子负责人 / 区域主负责人</td></tr><tr><td>搜索框</td><td>昵称、账号、手机号、身份名称、UID</td></tr><tr><td>左侧列表</td><td>可选账号；徽章「超管全开」「未授权」</td></tr><tr><td>右侧</td><td>自定义身份名称、套用模板、权限树</td></tr><tr><td>底部</td><td><strong>保存</strong></td></tr></tbody></table><h3 id="给某人开通权限-完整步骤" tabindex="-1">给某人开通权限（完整步骤） <a class="header-anchor" href="#给某人开通权限-完整步骤" aria-label="Permalink to &quot;给某人开通权限（完整步骤）&quot;">​</a></h3><ol><li>用身份 Tab 或搜索找到账号，在左侧<strong>点选</strong></li><li>（可选）填写 <strong>自定义身份名称</strong>（仅用于后台展示，如「XX 校区运营」）</li><li>（推荐）在「套用模板」中选择模板 → 点 <strong>套用</strong></li><li>按需增删菜单与按钮权限（可用全选 / 清空）</li><li>点 <strong>保存</strong></li></ol><p>保存后将<strong>替换该用户全部直接授权</strong>。已套用模板时，页面会提示「与直接授权合并生效」。</p><h3 id="解除模板" tabindex="-1">解除模板 <a class="header-anchor" href="#解除模板" aria-label="Permalink to &quot;解除模板&quot;">​</a></h3><p>选中账号后点 <strong>解除</strong>，仅取消与模板的绑定；直接勾选的权限仍保留，需再保存确认。</p><h3 id="超级管理员" tabindex="-1">超级管理员 <a class="header-anchor" href="#超级管理员" aria-label="Permalink to &quot;超级管理员&quot;">​</a></h3><p>超级管理员为全开权限，一般无需在本页逐项勾选。列表可能显示「超管全开」。</p><hr><h2 id="三、验证是否生效" tabindex="-1">三、验证是否生效 <a class="header-anchor" href="#三、验证是否生效" aria-label="Permalink to &quot;三、验证是否生效&quot;">​</a></h2><ol><li>用被授权账号重新登录管理后台（或退出再进）</li><li>侧栏应出现已勾选的菜单</li><li>打开一个写操作页面（如审核通过），确认按钮可用</li><li>未授权菜单不应出现；强行访问接口应提示无权限</li></ol><div class="tip custom-block"><p class="custom-block-title">改权后仍像没生效？</p><p>请对方<strong>退出重新登录</strong>。权限有短时缓存，多实例部署时一般会在保存后广播失效；仍不对可稍等片刻再试。</p></div><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>左侧选中后提示「当前未配置任何授权…」</td><td>必须勾选权限或套用模板后再保存，否则对方无法用后台</td></tr><tr><td>侧栏几乎是空的</td><td>未保存授权，或只勾了按钮没勾菜单访问</td></tr><tr><td>能进页面但不能点「通过/保存」</td><td>缺对应「按钮」权限</td></tr><tr><td>无法把「系统配置」分给区域负责人</td><td>设计如此：系统设置类权限仅超管/平台管理员可持有</td></tr><tr><td>套用模板后权限不对</td><td>先检查模板本身勾选项，再检查账号上是否又手工改过</td></tr></tbody></table><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/guide/admin-access">进入管理后台</a></li><li><a href="/config/my-modules">我的模块</a></li><li><a href="/config/system-settings">系统配置总览</a></li></ul>',42)])])}const u=a(d,[["render",l]]);export{b as __pageData,u as default};
